BEGIN TRANSACTION;
CREATE TABLE analytics_agents (id TEXT PRIMARY KEY, record TEXT NOT NULL);
CREATE TABLE analytics_cost_changes_v1 (
        root TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(root,id));
CREATE TABLE analytics_cost_projection_v1 (id TEXT PRIMARY KEY,root TEXT,packed TEXT NOT NULL);
CREATE TABLE analytics_cost_roots_v1 (
        root TEXT PRIMARY KEY,revision INTEGER NOT NULL,floor INTEGER NOT NULL);
CREATE TABLE analytics_cost_state_v1 (
        singleton INTEGER PRIMARY KEY CHECK(singleton=1), token TEXT NOT NULL);
INSERT INTO "analytics_cost_state_v1" VALUES(1,'5f89c011ff0da2c83245f30510a77690');
CREATE TABLE analytics_history (id TEXT PRIMARY KEY, agent TEXT NOT NULL, record TEXT NOT NULL);
CREATE TABLE analytics_items (
            id TEXT PRIMARY KEY, agent TEXT NOT NULL, root TEXT, thread TEXT, turn TEXT,
            at REAL NOT NULL, type TEXT, name TEXT, is_tool INTEGER NOT NULL, record TEXT NOT NULL);
CREATE TABLE analytics_limits (
            id INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, at REAL NOT NULL, record TEXT NOT NULL);
CREATE TABLE analytics_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO "analytics_meta" VALUES('trackingSince','1792689637.8667583');
CREATE TABLE analytics_notifications (
            id TEXT PRIMARY KEY, agent TEXT, root TEXT, method TEXT, hour INTEGER,
            count INTEGER NOT NULL, bytes INTEGER NOT NULL);
CREATE TABLE analytics_turns (
            id TEXT PRIMARY KEY, agent TEXT NOT NULL, root TEXT, at REAL NOT NULL, record TEXT NOT NULL);
CREATE TABLE analytics_usage (
            seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL,
            agent TEXT NOT NULL, root TEXT, thread TEXT, turn TEXT, at REAL NOT NULL, record TEXT NOT NULL);
CREATE TABLE analytics_usage_roots (root TEXT PRIMARY KEY, generation INTEGER NOT NULL);
CREATE INDEX analytics_turns_scope ON analytics_turns(agent,at);
CREATE INDEX analytics_limits_account_at ON analytics_limits(account, at);
CREATE INDEX analytics_usage_scope ON analytics_usage(agent,at);
CREATE INDEX analytics_usage_team ON analytics_usage(root,at);
CREATE INDEX analytics_usage_root_seq ON analytics_usage(root,seq);
CREATE INDEX analytics_usage_response ON analytics_usage(agent,thread,json_extract(record,'$.responseId'));
CREATE INDEX analytics_usage_thread ON analytics_usage(agent,thread,seq);
CREATE INDEX analytics_usage_migration ON analytics_usage(agent,seq);
CREATE INDEX analytics_items_scope ON analytics_items(agent,at);
CREATE INDEX analytics_items_team ON analytics_items(root,at);
CREATE INDEX analytics_items_tool ON analytics_items(name,at);
CREATE INDEX analytics_agents_root ON analytics_agents(json_extract(record,'$.rootId'));
CREATE INDEX analytics_cost_projection_seq_v1 ON analytics_cost_projection_v1(json_extract(packed,'$[0]'));
CREATE INDEX analytics_cost_changes_revision_v1 ON analytics_cost_changes_v1(root,revision);
CREATE TRIGGER analytics_cost_projection_insert_v1 AFTER INSERT ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT NEW.root,1,0 WHERE NEW.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,NEW.id,revision FROM analytics_cost_roots_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS NEW.root); END;
CREATE TRIGGER analytics_cost_projection_update_v1 AFTER UPDATE ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT NEW.root,1,0 WHERE NEW.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,NEW.id,revision FROM analytics_cost_roots_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS NEW.root AND NEW.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS NEW.root); INSERT INTO analytics_cost_roots_v1 SELECT OLD.root,1,0 WHERE OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,OLD.id,revision FROM analytics_cost_roots_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND OLD.root IS NOT NEW.root AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS OLD.root); END;
CREATE TRIGGER analytics_cost_projection_delete_v1 AFTER DELETE ON analytics_cost_projection_v1 BEGIN INSERT INTO analytics_cost_roots_v1 SELECT OLD.root,1,0 WHERE OLD.root IS NOT NULL ON CONFLICT(root) DO UPDATE SET revision=revision+1,floor=MAX(0,revision+1-8192); INSERT INTO analytics_cost_changes_v1 SELECT root,OLD.id,revision FROM analytics_cost_roots_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL ON CONFLICT(root,id) DO UPDATE SET revision=excluded.revision; DELETE FROM analytics_cost_changes_v1 WHERE root IS OLD.root AND OLD.root IS NOT NULL AND revision<=(SELECT floor FROM analytics_cost_roots_v1 WHERE root IS OLD.root); END;
